import{ref}from"vue";import{defineStore}from"pinia";import axios from"axios";export const useBookStore=defineStore("book",()=>{const apiUrl=import.meta.env.VITE_APP_API_URL,isLoading=ref(!1),datas=ref([]),fetchBook=async()=>{isLoading.value=!0;const res=await axios.get(apiUrl+"/fetchBook");datas.value=res.data.result};return fetchBook(),{apiUrl:apiUrl,isLoading:isLoading,datas:datas}});